  function openStorage(){if(window.MusicLabHost)return Promise.resolve(null);if(storageDB)return Promise.resolve(storageDB);if(storageOpening)return storageOpening;storageOpening=new Promise(resolve=>{try{const request=indexedDB.open('fable-instruments-v1',1);let done=false,timer=setTimeout(()=>{done=true;resolve(null);},2500);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('projects'))request.result.createObjectStore('projects');};request.onsuccess=()=>{clearTimeout(timer);const db=request.result;if(done){db.close();return;}storageDB=db;db.onversionchange=()=>{db.close();storageDB=null;storageOpening=null;};resolve(db);};request.onerror=request.onblocked=()=>{clearTimeout(timer);done=true;resolve(null);};}catch(_){resolve(null);}});return storageOpening;}
  function storageTransaction(db,mode,action){return new Promise((resolve,reject)=>{try{const tx=db.transaction('projects',mode),request=action(tx.objectStore('projects'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Browser storage is unavailable.'));}catch(error){reject(error);}});}
  function persist(){clearTimeout(persistTimer);persistTimer=setTimeout(async()=>{let text;try{text=S.serializeProject(state);}catch(error){say('Save project: '+error.message,true);return;}const db=await openStorage();if(db){try{await storageTransaction(db,'readwrite',store=>store.put(text,'current'));storageOkay=true;return;}catch(_){}}try{localStorage.setItem('fable-project-v1',text);storageOkay=true;}catch(_){storageOkay=false;say('Browser storage cannot keep this instrument. Save project downloads every sample and setting.');}},450);}
  async function recoverStoredProject(){const token=lifecycle,edit=revision,db=await openStorage();if(!db)return;try{const saved=await storageTransaction(db,'readonly',store=>store.get('current'));if(saved&&token===lifecycle&&edit===revision){const next=S.parseProject(saved);state=next;engine.setState(state);renderKeyboard();render();say('Your saved stock is ready for service.');}}catch(_){if(token===lifecycle&&edit===revision)say('Stored stock could not be opened. Save instrument keeps a portable copy.');}}
