  const field = (label,path,min,max,step=1,kind='master',type='range') => '<label class="field"><span>'+escape(label)+' <output data-output="'+escape(path)+'"></output></span><input type="'+type+'" data-'+kind+'-field="'+escape(path)+'" min="'+min+'" max="'+max+'" step="'+step+'"></label>';
