  function formatValue(path,value){if(typeof value==='boolean')return value?'On':'Off';if(typeof value!=='number')return value??'';if(['root','low','high','note'].includes(path))return noteName(value)+' · '+Math.round(value);if(path.endsWith('cutoff')||path==='tone')return value>=1000?(value/1000).toFixed(1)+' kHz':Math.round(value)+' Hz';if(path.includes('attack')||path.includes('decay')||path.includes('release')||path.includes('grainSize')||path==='crossfade')return value<1?Math.round(value*1000)+' ms':value.toFixed(2)+' s';return Number.isInteger(value)?String(value):value.toFixed(3).replace(/0+$/,'').replace(/\.$/,'');}
