  function fieldObject(el){for(const kind of ['zone','master','performance','lfo','route','step']){const path=el.dataset[kind+'Field'];if(path===undefined)continue;if(kind==='zone')return{object:zone(),path,kind};if(kind==='master')return{object:state.master,path,kind};if(kind==='performance')return{object:state.performance,path,kind};if(kind==='step')return{object:pattern().steps[selectedStep],path,kind};const [index,...parts]=path.split(':');return{object:kind==='lfo'?state.lfos[Number(index)]:state.modulation[Number(index)],path:parts.join(':'),kind};}return null;}
  function refreshFields(){document.querySelectorAll('[data-zone-field],[data-master-field],[data-performance-field],[data-lfo-field],[data-route-field],[data-step-field]').forEach(el=>{const info=fieldObject(el);if(!info?.object){el.disabled=true;return;}el.disabled=info.kind==='zone'&&['stretch','grainSize','grainDensity','jitter','position'].includes(info.path)&&info.object.engine!=='texture';const value=getPath(info.object,info.path);if(document.activeElement!==el){if(el.type==='checkbox')el.checked=!!value;else el.value=value??'';}const output=el.closest('.field')?.querySelector('output');if(output)output.textContent=formatValue(info.path,value);});if($('undo'))$('undo').disabled=!history.length;if($('redo'))$('redo').disabled=!future.length;}
  function zoneAdjust(z,path){if(path==='low'&&z.low>z.high)z.high=z.low;if(path==='high'&&z.high<z.low)z.low=z.high;if(path==='velLow'&&z.velLow>z.velHigh)z.velHigh=z.velLow;if(path==='velHigh'&&z.velHigh<z.velLow)z.velLow=z.velHigh;if(path==='start'&&z.start>=z.end)z.start=Math.max(0,z.end-.0001);if(path==='end'&&z.end<=z.start)z.end=Math.min(1,z.start+.0001);const epsilon=Math.min(.0001,(z.end-z.start)/4);z.loopStart=clamp(z.loopStart,z.start,z.end-epsilon);z.loopEnd=clamp(z.loopEnd,z.loopStart+epsilon,z.end);}
  const editing=new WeakSet();
  document.addEventListener('input',e=>{const el=e.target,info=fieldObject(el);if(!info?.object)return;let value=fieldValue(el);if(typeof value==='number'){if(!Number.isFinite(value))return;if(el.hasAttribute('min'))value=Math.max(Number(el.min),value);if(el.hasAttribute('max'))value=Math.min(Number(el.max),value);if(el.step==='1')value=Math.round(value);}if(!editing.has(el)){remember();editing.add(el);}setPath(info.object,info.path,value);if(info.kind==='zone')zoneAdjust(info.object,info.path);commit(false);if(info.kind==='zone'){drawWave();drawMap();drawEnvelopes();renderZoneList();}if(info.kind==='step')renderSteps();});
  document.addEventListener('change',e=>{const info=fieldObject(e.target);if(info){editing.delete(e.target);render();}});
  function renderZoneList(){if(!$('zoneList'))return;$('zoneList').innerHTML=state.zones.map((z,i)=>'<button type="button" class="zone-item zone-card'+(z.id===state.selectedZone?' selected':'')+(!z.enabled?' muted':'')+'" data-zone="'+escape(z.id)+'" aria-pressed="'+(z.id===state.selectedZone)+'"><i class="zone-color" style="--zone-color:'+escape(z.color||'#ff8d45')+';background:'+escape(z.color||'#ff8d45')+'"></i><span class="zone-name">'+escape(z.name||'Zone '+(i+1))+'</span><span class="zone-meta">'+noteName(z.low)+'–'+noteName(z.high)+' · v '+z.velLow+'–'+z.velHigh+(z.roundRobin?' · RR '+z.roundRobin:'')+'</span></button>').join('');}
  function renderSteps(){if(!$('steps'))return;const p=pattern(),start=sequencePage*16;$('steps').innerHTML=Array.from({length:Math.min(16,p.length-start)},(_,i)=>{const ix=i+start,step=p.steps[ix];return'<button type="button" class="step'+(step.on?' on':'')+(selectedStep===ix?' selected':'')+'" data-step="'+ix+'" aria-label="Step '+(ix+1)+', '+noteName(step.note)+', '+(step.on?'on':'off')+'" aria-pressed="'+step.on+'"><span class="step-number">'+String(ix+1).padStart(2,'0')+'</span><span class="step-note">'+noteName(step.note)+'</span><i class="step-velocity" style="width:'+Math.round(step.velocity*100)+'%"></i></button>';}).join('');if($('stepPageLabel'))$('stepPageLabel').textContent='Steps '+(start+1)+'–'+Math.min(p.length,start+16);if($('stepPagePrev'))$('stepPagePrev').disabled=sequencePage===0;if($('stepPageNext'))$('stepPageNext').disabled=(sequencePage+1)*16>=p.length;}
  function renderStepEditor(){if(!$('stepEditor'))return;$('stepEditor').innerHTML='<span class="step-label">STEP '+String(selectedStep+1).padStart(2,'0')+'</span><div class="control-grid">'+toggle('Enabled','on','step')+field('Note','note',0,127,1,'step','number')+field('Velocity','velocity',.01,1,.01,'step')+field('Gate','gate',.02,1,.01,'step')+field('Probability','probability',0,1,.01,'step')+field('Ratchets','ratchet',1,8,1,'step','number')+'</div>';}
  function renderKeyboard(){if(!$('keyboard'))return;const first=clamp(state.keyOctave*12,0,96),last=state.keyOctave===8?127:first+24,whites=[];for(let n=first;n<=last;n++)if(![1,3,6,8,10].includes(n%12))whites.push(n);let html='';for(let n=first;n<=last;n++){const black=[1,3,6,8,10].includes(n%12),index=whites.filter(k=>k<n).length,left=black?(index/whites.length*100-2.1):(whites.indexOf(n)/whites.length*100);html+='<button type="button" class="key '+(black?'black':'white')+'" data-note="'+n+'" aria-label="Play '+noteName(n)+'" aria-pressed="false" style="left:'+left+'%;width:'+(black?4.2:100/whites.length)+'%"><span>'+noteName(n)+'</span></button>';}$('keyboard').innerHTML=html;if($('octaveLabel'))$('octaveLabel').textContent=noteName(first)+'–'+noteName(last);refreshKeys();}
  function refreshKeys(){document.querySelectorAll('.key[data-note]').forEach(el=>{const note=Number(el.dataset.note),active=Array.from(held.values()).some(h=>h.note===note)||(noteVoices.get(note)?.size||0)>0;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});}
  function render(){const z=zone(),a=asset(z);if($('stockPlayingLabel'))$('stockPlayingLabel').textContent=state.name+' · '+state.zones.length+' '+(state.zones.length===1?'zone':'zones');if($('projectName')&&document.activeElement!==$('projectName'))$('projectName').value=state.name;if($('tempo')&&document.activeElement!==$('tempo'))$('tempo').value=state.tempo;if($('swing')&&document.activeElement!==$('swing'))$('swing').value=state.swing;if($('zoneCount'))$('zoneCount').textContent=state.zones.length+' / '+MAX_ZONES+' zones';if($('assetBudget'))$('assetBudget').textContent=state.assets.length+' / '+MAX_ASSETS+' samples · '+(budget()/1048576).toFixed(1)+' / 64 MB';if($('selectedZoneName'))$('selectedZoneName').textContent=z?.name||'No sample selected';if($('selectedZoneInfo'))$('selectedZoneInfo').textContent=a?(a.name+' · '+Number(a.duration).toFixed(2)+' s · '+(a.channels===1?'MONO':'STEREO')+' · '+noteName(z.root)):'Import a sound, or choose a sample zone.';if($('reuseAsset')){const previous=$('reuseAsset').value;$('reuseAsset').innerHTML='<option value="">Reuse a sample…</option>'+state.assets.map(a=>'<option value="'+escape(a.id)+'">'+escape(a.name)+'</option>').join('');$('reuseAsset').value=previous;}if($('patternSelect'))$('patternSelect').value=state.selectedPattern;if($('patternLength'))$('patternLength').value=pattern().length;selectedStep=Math.min(selectedStep,pattern().length-1);sequencePage=Math.min(sequencePage,Math.ceil(pattern().length/16)-1);renderZoneList();renderSteps();renderStepEditor();refreshFields();drawWave();drawMap();drawEnvelopes();updateTransport();if($('deleteZone'))$('deleteZone').disabled=!z;if($('duplicateZone'))$('duplicateZone').disabled=!z||state.zones.length>=MAX_ZONES;}
  function onNote(event){if(!event)return;const set=noteVoices.get(event.note)||new Set();if(event.on)set.add(event.voiceId??event.zoneId);else set.delete(event.voiceId??event.zoneId);if(set.size)noteVoices.set(event.note,set);else noteVoices.delete(event.note);refreshKeys();}
  function onStep(index){document.querySelectorAll('[data-step]').forEach(el=>el.classList.toggle('current',Number(el.dataset.step)===index));if(index>=0&&$('sequencePosition'))$('sequencePosition').textContent=String(index+1).padStart(2,'0')+' / '+pattern().length;}
  function updateMeters(m){if(!m)return;const peak=Math.max(0,Number(m.peak)||0);if($('peakMeter'))$('peakMeter').style.width=Math.min(100,Math.max(0,(20*Math.log10(Math.max(1e-6,peak))+60)/60*100))+'%';if($('peakReadout'))$('peakReadout').textContent=peak>1e-5?Math.round(20*Math.log10(peak))+' dB':'−∞ dB';if($('voiceCount'))$('voiceCount').textContent=(m.voices||0)+' / '+state.master.polyphony+' voices';if(typeof m.playing==='boolean'&&m.playing!==playing){playing=m.playing;updateTransport();}}
  function canvasSize(canvas,height){const rect=canvas.getBoundingClientRect(),ratio=Math.min(2,window.devicePixelRatio||1),width=Math.max(1,rect.width),h=rect.height||height;if(canvas.width!==Math.round(width*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(width*ratio);canvas.height=Math.round(h*ratio);}const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);return{ctx,width,height:h};}
  function selectedAudio(){const a=asset();if(!a)return null;return engine.getAssetAudio(a);}
